// OpenBitFun approval bridge for Pi RPC sessions.
//
// OpenBitFun launches `pi --mode rpc -e <this file>`. Before a tool call that
// may modify the environment runs, the bridge opens an RPC `select` dialog
// whose title starts with MARKER and carries the call as JSON. OpenBitFun
// answers with one of OPTIONS (or cancels, which blocks the call). No
// `timeout` is set, so a pending decision never resolves on its own; an
// aborted run dismisses it through `ctx.signal`.
//
// Generated by OpenBitFun; edits are overwritten.

const MARKER = "openbitfun-approval:";
const OPTIONS = ["allow_once", "allow_session", "reject_once", "reject_read_only"];
// Built-in tools that only read. `codemode` and `tool_search` only reach
// other tools, whose calls pass through this handler themselves.
const READ_ONLY = new Set(["read", "grep", "find", "ls", "codemode", "tool_search"]);

export default function (pi: any) {
  // Lets OpenBitFun verify that the bridge loaded (`get_commands`).
  pi.registerCommand("openbitfun-approvals", {
    description: "OpenBitFun approval bridge status",
    handler: async (_args: string, ctx: any) => {
      ctx.ui.notify("OpenBitFun approvals are active", "info");
    },
  });

  pi.on("tool_call", async (event: any, ctx: any) => {
    if (ctx.mode !== "rpc") return undefined;
    const tool = pi.getAllTools().find((candidate: any) => candidate.name === event.toolName);
    if (!needsApproval(event.toolName, tool?.annotations)) return undefined;
    const request = {
      toolCallId: event.toolCallId,
      parentToolCallId: event.parentToolCallId,
      toolName: event.toolName,
      input: event.input,
    };
    const choice = await ctx.ui.select(MARKER + JSON.stringify(request), OPTIONS, {
      signal: ctx.signal,
    });
    if (choice === "allow_once" || choice === "allow_session") return undefined;
    let reason = `${event.toolName} was not approved.`;
    if (choice === "reject_once") reason = `The user rejected this ${event.toolName} call.`;
    if (choice === "reject_read_only") {
      reason = `OpenBitFun read-only mode blocked ${event.toolName}: only tools that do not modify anything may run.`;
    }
    return { block: true, reason };
  });
}

// The rule Pi documents for confirming the calls Codex asks approval for.
function needsApproval(name: string, hints: any): boolean {
  if (READ_ONLY.has(name)) return false;
  if (hints?.destructiveHint === true) return true;
  return !hints?.readOnlyHint && ((hints?.destructiveHint ?? true) || (hints?.openWorldHint ?? true));
}
